exercise.solution:
fn verdict(choice: &str) -> &str {
    match choice {
        c if c.contains("24h") => "risk (long-lived, unrevokable)",
        c if c.contains("rotating refresh") => "good",
        c if c.contains("SHA-256") => "risk (too fast, needs slow KDF)",
        c if c.contains("argon2") => "good",
        _ => "unknown",
    }
}

fn main() {
    for c in [
        "JWT 24h expiry, no revocation",
        "short-lived access + rotating refresh",
        "passwords hashed with SHA-256",
        "argon2 with per-user salt",
    ] {
        println!("{}: {}", c, verdict(c));
    }
}
